//! Complete feature gate registry with protocol-defined pubkeys.
//!
//! Each feature is identified by a unique pubkey assigned by the Solana protocol.
//! These pubkeys are NOT derived from feature names — they are predefined
//! Ed25519 public keys that identify specific on-chain feature accounts.
//!
//! The registry contains all features recognized by the current protocol
//! (aligned to the reference upstream baseline abb557c7, 2026-06-02).
//! Features control runtime behavior changes and are activated through
//! on-chain governance.

