/// Check whether a feature name has been cleaned up (behavior hardcoded).
pub fn is_cleaned_up(name: &str) -> bool {
    CLEANED_UP_FEATURES.binary_search(&name).is_ok()
}

/// Look up a feature pubkey by its protocol name.
///
/// Returns the protocol-assigned pubkey for the given feature name,
/// or `None` if the feature is not in the registry.
pub fn feature_id(name: &str) -> Option<Pubkey> {
    FEATURE_REGISTRY
        .iter()
        .find(|(n, _)| *n == name)
        .map(|(_, bytes)| Pubkey::new(*bytes))
}

/// Look up a feature pubkey by name, panicking if not found.
///
/// Convenience wrapper for tests and initialization code where
/// the feature name is known to be valid.
pub fn feature_id_expect(name: &str) -> Pubkey {
    feature_id(name).unwrap_or_else(|| panic!("unknown feature: {}", name))
}

/// Check whether a given pubkey corresponds to any known feature.
pub fn is_known_feature(pubkey: &Pubkey) -> bool {
    FEATURE_REGISTRY
        .iter()
        .any(|(_, bytes)| pubkey.as_bytes() == bytes)
}

/// Get the feature name for a given pubkey, if it is a known feature.
pub fn feature_name(pubkey: &Pubkey) -> Option<&'static str> {
    FEATURE_REGISTRY
        .iter()
        .find(|(_, bytes)| pubkey.as_bytes() == bytes)
        .map(|(name, _)| *name)
}

/// Build a list of all known feature activations.
///
/// Returns one `FeatureActivation` per registry entry with `activation_slot: None`.
pub fn all_known_features() -> Vec<FeatureActivation> {
    FEATURE_REGISTRY
        .iter()
        .map(|(name, bytes)| FeatureActivation {
            feature_id: Pubkey::new(*bytes),
            activation_slot: None,
            description: name,
            cleaned_up: is_cleaned_up(name),
        })
        .collect()
}

