#[cfg(test)]
mod registry_tests {
    use super::*;

    #[test]
    fn registry_has_expected_count() {
        assert_eq!(FEATURE_REGISTRY.len(), FEATURE_COUNT);
    }

    #[test]
    fn feature_id_lookup_succeeds() {
        let pk = feature_id("deprecate_rewards_sysvar");
        assert!(pk.is_some());
        assert_ne!(pk.unwrap(), Pubkey::default());
    }

    #[test]
    fn feature_id_lookup_returns_none_for_unknown() {
        assert!(feature_id("nonexistent_feature_xyz").is_none());
    }

    /// W018 upstream sync: the 14 features added to align with reference baseline
    /// abb557c7 must be registered, resolvable, and have unique non-default ids.
    #[test]
    fn w018_synced_features_registered() {
        let synced = [
            "commission_rate_in_basis_points",
            "create_account_allow_prefund",
            "define_ltds_fee_only_semantics",
            "delay_commission_updates",
            "direct_account_pointers_in_program_input",
            "disable_sbpf_v0_v1_v2_deployment",
            "discard_unexpected_data_complete_shreds",
            "enable_sha512_syscall",
            "loader_v3_minimum_extend_program_size",
            "replace_spl_token_with_p_token",
            "syscall_parameter_address_restrictions",
            "upgrade_bpf_stake_program_to_v5",
            "validate_chained_block_id",
            "virtual_address_space_adjustments",
        ];
        let mut seen = std::collections::HashSet::new();
        for name in synced {
            let pk = feature_id(name).unwrap_or_else(|| panic!("{name} not registered"));
            assert_ne!(pk, Pubkey::default(), "{name} has default id");
            assert!(is_known_feature(&pk), "{name} not recognized as known");
            assert_eq!(
                feature_name(&pk),
                Some(name),
                "{name} name round-trip failed"
            );
            assert!(seen.insert(pk), "duplicate id for {name}");
        }
    }

    #[test]
    fn all_features_have_unique_pubkeys() {
        let mut seen = std::collections::HashSet::new();
        for (name, bytes) in FEATURE_REGISTRY.iter() {
            assert!(seen.insert(bytes), "duplicate pubkey for feature: {}", name);
        }
    }

    #[test]
    fn all_features_have_unique_names() {
        let mut seen = std::collections::HashSet::new();
        for (name, _) in FEATURE_REGISTRY.iter() {
            assert!(seen.insert(name), "duplicate feature name: {}", name);
        }
    }

    /// W029 upstream re-baseline: the new feature
    /// `validate_chained_block_id_2` must be registered, resolvable, and
    /// distinct from the v1 `validate_chained_block_id`.
    #[test]
    fn w029_validate_chained_block_id_2_registered() {
        let v1 = feature_id("validate_chained_block_id").expect("v1 not registered");
        let v2 = feature_id("validate_chained_block_id_2").expect("v2 not registered");
        assert_ne!(v2, Pubkey::default(), "v2 has default id");
        assert_ne!(v1, v2, "v1 and v2 must have distinct ids");
        assert!(is_known_feature(&v2), "v2 not recognized as known");
        assert_eq!(feature_name(&v2), Some("validate_chained_block_id_2"));
    }

    #[test]
    fn named_accessor_matches_registry_lookup() {
        assert_eq!(
            deprecate_rewards_sysvar(),
            feature_id("deprecate_rewards_sysvar").unwrap()
        );
        assert_eq!(enable_loader_v4(), feature_id("enable_loader_v4").unwrap());
        assert_eq!(
            enable_durable_nonce(),
            feature_id("enable_durable_nonce").unwrap()
        );
    }

    #[test]
    fn is_known_feature_works() {
        let pk = deprecate_rewards_sysvar();
        assert!(is_known_feature(&pk));
        assert!(!is_known_feature(&Pubkey::default()));
    }

    #[test]
    fn feature_name_round_trips() {
        let pk = enable_loader_v4();
        assert_eq!(feature_name(&pk), Some("enable_loader_v4"));
    }

    #[test]
    fn all_known_features_returns_correct_count() {
        let all = all_known_features();
        assert_eq!(all.len(), FEATURE_COUNT);
        // All should have None activation
        assert!(all.iter().all(|f| f.activation_slot.is_none()));
    }
}
